const menu=document.querySelector('.menu'),nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close −':'Menu +';});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu +';}));
const lightbox=document.querySelector('#lightbox');
document.querySelectorAll('.photo').forEach(button=>button.addEventListener('click',()=>{lightbox.querySelector('img').src=button.dataset.image;lightbox.querySelector('img').alt=button.querySelector('img').alt;lightbox.querySelector('p').textContent=button.dataset.caption;lightbox.showModal();}));
document.querySelector('#close-gallery').addEventListener('click',()=>lightbox.close());
lightbox.addEventListener('click',event=>{if(event.target===lightbox){const r=lightbox.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)lightbox.close();}});
document.querySelector('#enquiry').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);document.querySelector('#message').value=`Hello Chiaroscuro Weddings!\n\nWe’re ${data.get('name').trim()} and ${data.get('partner').trim()}, and we’re planning our celebration on ${data.get('date')} at ${data.get('location').trim()}.\n\nWe’re interested in ${data.get('service').toLowerCase()}.\n${data.get('story').trim()?`\nA little about our plans: ${data.get('story').trim()}\n`:''}\nCould you share your availability and collections?`;document.querySelector('#draft').hidden=false;document.querySelector('#copy-status').textContent='';document.querySelector('#message').focus();});
document.querySelector('.copy').addEventListener('click',async()=>{const field=document.querySelector('#message');try{await navigator.clipboard.writeText(field.value);document.querySelector('#copy-status').textContent='Copied. Open Instagram and paste it into your message.';}catch{field.focus();field.select();document.querySelector('#copy-status').textContent='Select and copy the draft, then paste it into Instagram.';}});
